// NEO fork — the thesaurus build script refuses data it cannot read (adr-002)
//
// The committed shards are generated by neo-ext/tools/build-thesaurus.js. A
// marker that is not understood must stop the build, or it reaches the
// manuscript again as part of a word.

'use strict';

const test = require('node:test');
const assert = require('node:assert');

const build = require('../neo-ext/tools/build-thesaurus.js');

test('parse: relation markers become rel and stay out of the word', () => {
  const words = build.parse('good|2\n(adj)|fine|bad (antonym)|big (similar term)\n(adj)|good (generic term)\n');
  assert.deepEqual(words.get('good'), [
    { pos: 'adj', syns: [{ w: 'fine', rel: '' }, { w: 'bad', rel: 'antonym' }, { w: 'big', rel: 'similar' }] },
    { pos: 'adj', syns: [{ w: 'good', rel: 'generic' }] }
  ]);
});

test('parse: an unknown marker stops the build', () => {
  assert.throws(() => build.parse('word|1\n(noun)|other (also related)\n'), /unknown marker/);
});

test('parse: a parenthetical that is not a marker stops the build', () => {
  assert.throws(() => build.parse('word|1\n(noun)|other (fig.)\n'), /unparsed marker/);
});

test('parse: a malformed sense line names the headword', () => {
  assert.throws(() => build.parse('word|1\n(noun) broken\n'), /malformed sense for "word"/);
});
